const espera = (ms) => new Promise((ok) => setTimeout(ok, ms));

async function consultarGps(camioneta) {
  await espera(300);                         // simula una llamada de red
  return `${camioneta}: posición recibida`;
}

// 1) En fila: cada await espera a que termine la anterior
let t0 = Date.now();
for (const c of ["A", "B", "C"]) await consultarGps(c);
console.log("en fila:", Math.round((Date.now() - t0) / 100) * 100, "ms");

// 2) Juntas: las tres esperas corren a la vez
t0 = Date.now();
const respuestas = await Promise.all(["A", "B", "C"].map(consultarGps));
console.log(respuestas.join(" | "));
console.log("juntas:", Math.round((Date.now() - t0) / 100) * 100, "ms");

